def read_table_prep(
    values_path,
    col_id,

    col_sid='sample id',
    col_group=None,
    
    mod_name=None, #exp_tpm/me_del
    value_name=None, # custom value name e.g. {mod_name} log10
    
    ## filter
    sids=None,
    ids=None,
    
    ## mdata to map
    var=None,
    obs=None,

    kws_read_table=dict(
                use_paths=True,
                fast=5,
        ),
    fmt='lin', # melt
    # dtype='float',
    verbose=False,
    ):
    """
    Unified reader.
    """
    if values_path.endswith('.h5ad') or values_path.endswith('.h5mu'):
        ## get the dataframe
        if values_path.endswith('.h5ad'):
            dt1=ad.read_h5ad(values_path, backed='r')
            logging.info(dt1)
            if mod_name is None:
                mod_name=list(dt1.layers.keys())[0]

            df0_vars=(
                dt1
                .to_df(layer=mod_name)
                # sids,ids -> ids,sids
                .T
                )
            
            uns=dt1.uns
            if var is None: #custom
                var=dt1.var.reset_index()
                
        elif values_path.endswith('.h5mu'):
            import mudata as md
            dt1=md.read(values_path, backed=True)
            logging.info(dt1)
            # k=dt1.mod_names[0]
            if mod_name is None:
                mod_name=dt1.mod_names[0]
            
            df0_vars=(
                dt1
                .mod[mod_name].to_df()
                # sids,ids -> ids,sids
                .T
                )
            uns=dt1.mod[mod_name].uns
            if var is None: #custom
                var=dt1.mod[mod_name].var.reset_index()
                
        value_name=uns.get('col',mod_name)
        del uns
        dt1.file.close()
    else:
        df0_vars=(
            read_table(
                values_path,
                **kws_read_table,
            )
        )
        df0_vars=df0_vars.drop(['index'],axis=1,errors='ignore')
    logging.info(f"cols={df0_vars.columns.tolist()}")
    if col_group in df0_vars:
        ## set aside until melt
        df_ids=df0_vars.loc[:,[col_id,col_group]]
        df0_vars=df0_vars.drop([col_group],axis=1,errors='ignore')

    _melted=col_sid in df0_vars and col_id in df0_vars
    
    ## infer value_name
    if value_name is None:
        value_name=mod_name
        del mod_name
    if value_name is None:
        if _melted:
            value_name=df0_vars.select_dtypes('float').columns.tolist()
            assert len(value_name)==1, value_name
            value_name=value_name[0]

    ## filtering (before melting for sparing memory)
    if not _melted:
        # if df0_vars.index.names != [col_id]:
        if col_id in df0_vars:
            df0_vars=df0_vars.set_index(col_id)
        df0_vars=loca(
            df0_vars,
            ids,
            sids,
        )
        
    ## out mat    
    if fmt=='mat':
        if not _melted:
            return df0_vars
        else:
            # sids=df0_vars.select_dtypes(dtype).columns.tolist()
            # print(col_id,col_sid,value_name)
            return (
                df0_vars
                    .pivot(
                        index=col_id,
                        columns=col_sid,
                        values=value_name,
                    )
            )
    ## filtering (before melting for sparing memory)
    if not _melted:
        df0_vars=loca(
            df0_vars,
            ids,
            sids,
        )
            
        df0_vars=(
            df0_vars
            .melt(
                ignore_index=False,
                value_name=value_name,
                var_name=col_sid,
            )
            .reset_index()
        )
        if 'df_ids' in locals():
            df0_vars=(
                df_ids
                .merge(
                    right=df0_vars,
                    how='inner',
                    on=col_id,
                    validate='1:m',
                )
                )
        
    _melted=col_sid in df0_vars and col_id in df0_vars
    assert _melted, df0_vars.columns.tolist()
    
    df0_vars=(
        df0_vars
            .astype(
                {
                    **{
                        col_id:str,
                        col_sid:str,
                    },
                    **({} if col_group not in df0_vars else {
                        col_group:str
                    }),
                },
            errors='ignore',
            )
    )
    
    if var is not None:
        df0_vars=(
            df0_vars
            .merge(
                right=var,
                on=col_id,
                how='inner',
                validate="m:1",
            )
        )
    if obs is not None:
        df0_vars=(
            df0_vars
            .merge(
                right=obs,
                on=col_sid,
                how='inner',
                validate="m:1",
            )
        )
    logging.info(f"{df0_vars.shape} {_get_preview_log_str(df0_vars.head(1))}")
    return df0_vars
    
