def to_dataset(
    dfs_values,
    outp,
    ):
    """
    To dataset.

    dfs_values:
        mods: 
            mod1: x
            mod2: x
        obs
        var
    """
    kws_write={}
    if outp.endswith('h5ad'):
        for i,(mod_name,df_x) in enumerate(dfs_values['mods'].items()):
            df_x=(
                df_x
                .sort_index(
                    axis=0,
                )
                .sort_index(
                    axis=1,
                )
                )
            if i==0:
                dt1 = ad.AnnData(
                    X=df_x.values,  # Main data matrix (expression data)
                    obs=dfs_values['obs'].loc[df_x.index.tolist(),:],  # Metadata for samples
                    var=dfs_values['var'].loc[df_x.columns.tolist(),:],  # Metadata for isoforms
                )
                dt1.layers[mod_name]=dt1.X
            else:
                assert (df_x.columns==dt1.var.index).all()
                assert (df_x.index==dt1.obs.index).all()
                dt1.layers[mod_name]=df_x.values
        logging.info(dt1)

        kws_write=dict(compression="gzip")
            
        # return dt1        
    elif outp.endswith('h5mu'):
        import mudata as md
        md.set_options(pull_on_update=False)        
        dts={}
        for mod_name,df_x in dfs_values['mods'].items():
            df_x=(
                df_x
                .sort_index(
                    axis=0,
                )
                .sort_index(
                    axis=1,
                )
                )
            dts[mod_name] = ad.AnnData(
                X=df_x.values,  # Main data matrix (expression data)
                obs=dfs_values['obs'].loc[df_x.index.tolist(),:],  # Metadata for samples
                var=dfs_values['var'].loc[df_x.columns.tolist(),:],  # Metadata for isoforms
            )
        dt1 = md.MuData(
            dts,
            axis=1
        )
        logging.info(dt1)
        assert (dts[mod_name].var.index==dt1.var.index).all()
        assert (dts[mod_name].obs.index==dt1.obs.index).all()
        dt1.var=dts[mod_name].var
        dt1.obs=dts[mod_name].obs

    Path(outp).parent.mkdir(parents=True,exist_ok=True)
    dt1.write(
        outp,
        **kws_write,
        )
    return outp

def read_mods_df(
    mods_cfg,
    col_id,
    col_group,
    col_sid='sample id',
    ):
    dfs=[]
    for k in mods_cfg:
        dfs.append(
            read_table_prep(
                mods_cfg[k]['path'],
                col_id=col_id,
                col_group=col_group,
                mod_name=mods_cfg[k]['col'],
            )
            )
    from roux.lib.dfs import merge_dfs
    return (
        merge_dfs(
            dfs,
            how='outer',
            on=[col_id,col_group,col_sid],
            validate='1:1'
        )
        .fillna({k:mods_cfg[k]['fillna'] for k in mods_cfg})
    )

def to_mods_dt(
    mods_cfg,
    outp,
    col_id,
    col_group,
    col_sid='sample id',
    ):
    df_merged=read_mods_df(
        mods_cfg,
        col_id=col_id,
        col_group=col_group,
        col_sid=col_sid,        
        )
    # df_merged.head()
    df_ids=(df_merged.loc[:,[col_id,col_group]].drop_duplicates().sort_values([col_id,col_group]))
    # df_ids
    Path(outp).parent.mkdir(parents=True,exist_ok=True)
    layers={
        k:(
            df_merged
            .pivot(
                index=col_sid,
                columns=col_id,
                values=mods_cfg.get('col',k),
            )
            .loc[:,df_ids[col_id].tolist()]
            # .set_index(col_id)
            .sort_index(axis=0)
            ) for k in mods_cfg
    }
    # return layers
    df_obs=layers[list(layers.keys())[0]].T.describe().T
    if outp.endswith('.h5ad'):
        dt = ad.AnnData(
                # X=df1_freq.values,
                obs=df_obs,
                var=df_ids.set_index(col_id),
                layers=layers,
                uns=mods_cfg,
            )
        dt.write(outp, compression="gzip")
    elif outp.endswith('.h5mu'):
        # logging.warning("h5mu is being saved, where h5ad should be preferred.")
        ## TODO: MuData because both var and obs do not necessarily align/be shared across modalities

        dt=md.MuData(
            {
                k:ad.AnnData(
                    X=df.values,
                    obs=df_obs,
                    var=df_ids.set_index(col_id),
                    uns=mods_cfg[k],
                ) for k,df in layers.items()
            },
            axis=1
        )
        dt.write(outp, compression="gzip")
    logging.info(dt)
    dt.file.close()
    return outp
